# Initially generated by GitHub Copilot.
"""Helpers for FOI-driven z-trivial k/q scope and lookup maps."""

import json

from foi import kq_trivial_sug as kqs
from mb_cmn import bib_locales as tbn
from mb_cmn import file_io
from mb_cmn import paths
from mb_cmn import uni_denorm as udn

DEFAULT_FOI_KQ_SIMPLE_PATH = str(
    paths.repo_root() / "gh-pages" / "MAM-with-doc" / "foi" / "foi-kq-simple.json"
)

_Z_TRIVIAL_PREFIX = "z-trivial/"
_MISC_SUBTYPE = "misc"


def scope_book_chapters(foi_json_path=DEFAULT_FOI_KQ_SIMPLE_PATH, include_misc=False):
    """Return [{"book39": ..., "chapter": ...}] for z-trivial rows.

    The list is deduplicated and sorted canonically by book order then chapter.
    """
    pairs = set()
    for row in _load_foi_rows(foi_json_path):
        subtype = _z_trivial_subtype(row)
        if subtype is None:
            continue
        if subtype == _MISC_SUBTYPE and not include_misc:
            continue
        book39, chapter, _verse = tbn.parse_short_bcv(row["bcv_short"])
        pairs.add((book39, chapter))
    sorted_pairs = sorted(pairs, key=lambda pair: (tbn.get_bknu(pair[0]), pair[1]))
    return [{"book39": book39, "chapter": chapter} for book39, chapter in sorted_pairs]


def write_scope_book_chapters_json(
    out_json_path,
    foi_json_path=DEFAULT_FOI_KQ_SIMPLE_PATH,
    include_misc=False,
):
    """Write FOI-derived chapter scope JSON to out_json_path."""
    scoped = scope_book_chapters(foi_json_path, include_misc=include_misc)
    file_io.json_dump_to_file_path(scoped, out_json_path)


def subtype_by_bcv_pqere(
    foi_json_path=DEFAULT_FOI_KQ_SIMPLE_PATH,
    include_misc=True,
):
    """Return {(bcv_short, pqere): classifier subtype} for z-trivial rows."""
    out = {}
    for row in _load_foi_rows(foi_json_path):
        row_subtype = _z_trivial_subtype(row)
        if row_subtype is None:
            continue
        subtype = kqs.expected_classifier_subtype_for_foi_row(row_subtype, row)
        if subtype == _MISC_SUBTYPE and not include_misc:
            continue
        pqere = udn.give_std_mark_order(row["pqere"])
        key = row["bcv_short"], pqere
        prev = out.get(key)
        assert prev in (None, subtype), (key, prev, subtype)
        out[key] = subtype
    return out


def _z_trivial_subtype(row):
    fp = row["fp"]
    if not fp.startswith(_Z_TRIVIAL_PREFIX):
        return None
    subtype = fp[len(_Z_TRIVIAL_PREFIX) :]
    assert subtype, row
    return subtype


def _load_foi_rows(foi_json_path):
    with open(foi_json_path, "r", encoding="utf-8") as json_in_fp:
        rows = json.load(json_in_fp)
    assert isinstance(rows, list), foi_json_path
    return rows
